SELECT SUM(CASE WHEN (esperado='RECHAZAR' AND resultado='RECHAZADO') OR (esperado='ACEPTAR' AND resultado='ACEPTADO') THEN 1 ELSE 0 END) AS correctas, COUNT(*) AS total FROM @r;
SELECT n, esperado, prueba, resultado, CASE WHEN (esperado='RECHAZAR' AND resultado='RECHAZADO') OR (esperado='ACEPTAR' AND resultado='ACEPTADO') THEN 'OK' ELSE 'REVISAR' END AS veredicto, detalle FROM @r ORDER BY CASE WHEN (esperado='RECHAZAR' AND resultado='RECHAZADO') OR (esperado='ACEPTAR' AND resultado='ACEPTADO') THEN 1 ELSE 0 END, n;
SELECT (SELECT COUNT(*) FROM sys.tables) AS tablas, (SELECT COUNT(*) FROM sys.views) AS vistas, (SELECT COUNT(*) FROM sys.triggers) AS triggers,
 (SELECT COUNT(*) FROM sys.indexes i JOIN sys.tables t ON t.object_id=i.object_id WHERE i.is_primary_key=0 AND i.is_unique_constraint=0 AND i.type>0) AS indices,
 (SELECT COUNT(*) FROM sys.foreign_keys) AS fks, (SELECT COUNT(*) FROM sys.check_constraints) AS checks;
SELECT serie, numero, total, pagado, saldo, estado_pago FROM vw_comprobante_saldo WHERE saldo > 0;
SELECT codigo_interno, descripcion, dias_restantes FROM vw_plazos_por_vencer ORDER BY dias_restantes;
